### Option 2: Role Selection Dropdown

```html
<!-- Dynamic dropdown populated from /api/admin/roles -->
<form onsubmit="handleRegisterWithRole(event)">
  <input type="email" id="email" required />
  <input type="password" id="password" required />

  <label>I want to be a:</label>
  <select id="role" required>
    <option value="">-- Select Role --</option>
    <!-- Populated by JavaScript -->
  </select>

  <button type="submit">Sign Up</button>
</form>

<script>
// Load available public roles
async function loadPublicRoles() {
  const response = await fetch('/api/admin/roles');
  const result = await response.json();

  const publicRoles = result.data.filter(r => r.registrationType === 'public');
  const dropdown = document.getElementById('role');

  publicRoles.forEach(role => {
    const option = document.createElement('option');
    option.value = role.name;
    option.textContent = `${role.name} - ${role.description}`;
    dropdown.appendChild(option);
  });
}

async function handleRegisterWithRole(event) {
  event.preventDefault();
  const response = await fetch('/api/auth/register', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({
      email: document.getElementById('email').value,
      password: document.getElementById('password').value,
      role: document.getElementById('role').value  // User-selected role
    })
  });

  const result = await response.json();
  if (result.success) {
    console.log('Registered as:', result.data.role);
    // Redirect to login
  } else {
    alert('Error: ' + result.message);
  }
}

// Load on page load
window.addEventListener('load', loadPublicRoles);
</script>
```

