### Option 3: Conditional Role Selection

```html
<!-- Show role dropdown only if public roles exist -->
<form onsubmit="handleRegister(event)">
  <input type="email" id="email" required />
  <input type="password" id="password" required />

  <div id="roleSelector"></div>

  <button type="submit">Sign Up</button>
</form>

<script>
async function setupForm() {
  const response = await fetch('/api/admin/roles');
  const result = await response.json();
  const publicRoles = result.data.filter(r => r.registrationType === 'public');

  if (publicRoles.length === 1) {
    // Only 1 public role - auto-select, hide dropdown
    document.getElementById('roleSelector').innerHTML = 
      `<p>You will be registered as: <strong>${publicRoles[0].name}</strong></p>`;
  } else if (publicRoles.length > 1) {
    // Multiple public roles - show dropdown
    let html = '<label>Select your role:</label><select id="role" required>';
    publicRoles.forEach(role => {
      html += `<option value="${role.name}">${role.name} - ${role.description}</option>`;
    });
    html += '</select>';
    document.getElementById('roleSelector').innerHTML = html;
  }
}

async function handleRegister(event) {
  event.preventDefault();
  const roleElement = document.getElementById('role');
  const payload = {
    email: document.getElementById('email').value,
    password: document.getElementById('password').value
  };

  if (roleElement) {
    payload.role = roleElement.value;
  }

  const response = await fetch('/api/auth/register', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(payload)
  });

  const result = await response.json();
  if (result.success) {
    console.log('Registered as:', result.data.role);
  }
}

window.addEventListener('load', setupForm);
</script>
```
